#ifndef GEMM_BF16_VAR_MNK_KERNEL_H
#define GEMM_BF16_VAR_MNK_KERNEL_H

#include <hip/hip_runtime.h>
#include <hip/hip_bfloat16.h>
#include <cstdint>

hipError_t launch_gemm_bf16_var_mnk(
    const hip_bfloat16* A,
    const hip_bfloat16* B,
    hip_bfloat16* C,
    int M,
    int N,
    int K,
    hipStream_t stream);

#endif // GEMM_BF16_VAR_MNK_KERNEL_H

#include "kernel.h"

#include <cstddef>
#include <cstdint>

namespace {

constexpr int TILE_M = 16;
constexpr int TILE_N = 16;
constexpr int TILE_K = 16;

__device__ __forceinline__ float bf16_to_float(hip_bfloat16 x) {
    return static_cast<float>(x);
}

__global__ void gemm_tiled_direct_kernel(
    const hip_bfloat16* __restrict__ A,
    const hip_bfloat16* __restrict__ B,
    hip_bfloat16* __restrict__ C,
    int M, int N, int K) {

    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_N][TILE_K];

    const int tx = threadIdx.x; // [0, TILE_N)
    const int ty = threadIdx.y; // [0, TILE_M)

    const int m = blockIdx.y * TILE_M + ty;
    const int n = blockIdx.x * TILE_N + tx;

    float acc = 0.0f;

    const int n_tile_base = blockIdx.x * TILE_N;

    for (int k0 = 0; k0 < K; k0 += TILE_K) {
        const int kA = k0 + tx;
        if (m < M && kA < K) {
            As[ty][tx] = bf16_to_float(A[static_cast<int64_t>(m) * K + kA]);
        } else {
            As[ty][tx] = 0.0f;
        }

        const int b_row = n_tile_base + ty;
        const int kB = k0 + tx;
        if (b_row < N && kB < K) {
            Bs[ty][tx] = bf16_to_float(B[static_cast<int64_t>(b_row) * K + kB]);
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc += As[ty][kk] * Bs[tx][kk];
        }

        __syncthreads();
    }

    if (m < M && n < N) {
        C[static_cast<int64_t>(m) * N + n] = __float2bfloat16(acc);
    }
}

__global__ void splitk_gemm_tiled_kernel(
    const hip_bfloat16* __restrict__ A,
    const hip_bfloat16* __restrict__ B,
    float* __restrict__ partial,
    int M, int N, int K,
    int part_size) {

    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_N][TILE_K];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int m = blockIdx.y * TILE_M + ty;
    const int n = blockIdx.x * TILE_N + tx;
    const int p = blockIdx.z;

    if (m >= M || n >= N) return;

    const int k_begin = p * part_size;
    const int k_end = (k_begin + part_size < K) ? (k_begin + part_size) : K;
    if (k_begin >= k_end) return;

    float acc = 0.0f;
    const int n_tile_base = blockIdx.x * TILE_N;

    for (int k0 = k_begin; k0 < k_end; k0 += TILE_K) {
        const int kA = k0 + tx;
        if (kA < k_end) {
            As[ty][tx] = bf16_to_float(A[static_cast<int64_t>(m) * K + kA]);
        } else {
            As[ty][tx] = 0.0f;
        }

        const int b_row = n_tile_base + ty;
        const int kB = k0 + tx;
        if (b_row < N && kB < k_end) {
            Bs[ty][tx] = bf16_to_float(B[static_cast<int64_t>(b_row) * K + kB]);
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc += As[ty][kk] * Bs[tx][kk];
        }

        __syncthreads();
    }

    const int64_t elem_idx = static_cast<int64_t>(m) * N + n;
    partial[static_cast<int64_t>(p) * static_cast<int64_t>(M) * N + elem_idx] = acc;
}

__global__ void splitk_merge_kernel(
    const float* __restrict__ partial,
    hip_bfloat16* __restrict__ C,
    int64_t elements,
    int partitions) {

    const int64_t idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx >= elements) return;

    float acc = 0.0f;
    for (int p = 0; p < partitions; ++p) {
        acc += partial[static_cast<int64_t>(p) * elements + idx];
    }
    C[idx] = __float2bfloat16(acc);
}

} // namespace

hipError_t launch_gemm_bf16_var_mnk(
    const hip_bfloat16* A,
    const hip_bfloat16* B,
    hip_bfloat16* C,
    int M,
    int N,
    int K,
    hipStream_t stream) {

    if (M <= 0 || N <= 0) {
        return hipSuccess;
    }

    const int64_t elements = static_cast<int64_t>(M) * static_cast<int64_t>(N);

    if (K <= 0) {
        return hipMemsetAsync(
            C,
            0,
            static_cast<size_t>(elements) * sizeof(hip_bfloat16),
            stream);
    }

    const bool k_dominant = (K >= 2048) && (elements <= 262144);
    const int part_size = k_dominant ? 1024 : K;
    const int partitions = (K + part_size - 1) / part_size;

    if (partitions == 1) {
        dim3 block(TILE_N, TILE_M, 1);
        dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M, 1);

        hipLaunchKernelGGL(
            gemm_tiled_direct_kernel,
            grid,
            block,
            0,
            stream,
            A, B, C, M, N, K);

        return hipGetLastError();
    }

    float* partial = nullptr;
    const size_t partial_bytes =
        static_cast<size_t>(elements) * static_cast<size_t>(partitions) * sizeof(float);

    hipError_t err = hipMalloc(reinterpret_cast<void**>(&partial), partial_bytes);
    if (err != hipSuccess) return err;

    {
        dim3 block(TILE_N, TILE_M, 1);
        dim3 grid(
            (N + TILE_N - 1) / TILE_N,
            (M + TILE_M - 1) / TILE_M,
            partitions);

        hipLaunchKernelGGL(
            splitk_gemm_tiled_kernel,
            grid,
            block,
            0,
            stream,
            A, B, partial, M, N, K, part_size);

        err = hipGetLastError();
        if (err != hipSuccess) {
            hipFree(partial);
            return err;
        }
    }

    {
        constexpr int threads = 256;
        const int blocks = static_cast<int>((elements + threads - 1) / threads);

        hipLaunchKernelGGL(
            splitk_merge_kernel,
            dim3(blocks),
            dim3(threads),
            0,
            stream,
            partial, C, elements, partitions);

        err = hipGetLastError();
        if (err != hipSuccess) {
            hipFree(partial);
            return err;
        }
    }

    err = hipFree(partial);
    return err;
}

#include <torch/extension.h>
#include <ATen/BFloat16.h>
#include <ATen/hip/HIPContext.h>
#include <c10/hip/HIPGuard.h>
#include <hip/hip_runtime.h>
#include <pybind11/pybind11.h>

#include <limits>

#include "kernel.h"

namespace py = pybind11;

torch::Tensor run(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be 2D, got dim=", A.dim());
    TORCH_CHECK(B.dim() == 2, "B must be 2D, got dim=", B.dim());

    const int64_t M64 = A.size(0);
    const int64_t K64 = A.size(1);
    const int64_t N64 = B.size(0);

    TORCH_CHECK(
        B.size(1) == K64,
        "Shape mismatch: A is [", M64, ", ", K64, "] but B is [", N64, ", ", B.size(1), "]");

    TORCH_CHECK(M64 <= std::numeric_limits<int>::max(), "M too large");
    TORCH_CHECK(N64 <= std::numeric_limits<int>::max(), "N too large");
    TORCH_CHECK(K64 <= std::numeric_limits<int>::max(), "K too large");

    int device_index = 0;
    if (A.is_hip()) {
        device_index = A.get_device();
    }
    if (B.is_hip()) {
        if (A.is_hip()) {
            TORCH_CHECK(B.get_device() == device_index, "A and B must be on the same HIP device");
        } else {
            device_index = B.get_device();
        }
    }

    c10::hip::HIPGuard device_guard(device_index);
    c10::Device gpu_device(c10::DeviceType::HIP, device_index);

    auto A_gpu = A.to(gpu_device, torch::kBFloat16, false, false).contiguous();
    auto B_gpu = B.to(gpu_device, torch::kBFloat16, false, false).contiguous();

    auto C_gpu = torch::empty(
        {M64, N64},
        torch::TensorOptions().device(gpu_device).dtype(torch::kBFloat16));

    auto stream = at::hip::getCurrentHIPStream(device_index);

    hipError_t status = launch_gemm_bf16_var_mnk(
        reinterpret_cast<const hip_bfloat16*>(A_gpu.data_ptr<at::BFloat16>()),
        reinterpret_cast<const hip_bfloat16*>(B_gpu.data_ptr<at::BFloat16>()),
        reinterpret_cast<hip_bfloat16*>(C_gpu.data_ptr<at::BFloat16>()),
        static_cast<int>(M64),
        static_cast<int>(N64),
        static_cast<int>(K64),
        stream.stream());

    TORCH_CHECK(
        status == hipSuccess,
        "launch_gemm_bf16_var_mnk failed: ",
        hipGetErrorString(status));

    return C_gpu.to(torch::kCPU);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("run", &run, py::arg("A"), py::arg("B"), "BF16 GEMM C = A @ B^T");
}
